fired.program:
kind thread from base
  letter N
  form to: Agent, typed: [Agent], names: [Agent], text: Text, addressed: Named | Unnamed | Sent(by: Agent), follows: Ticket?, label: Text?
  result
    Done(why: Text)       /// the work it carried is done; why says how (`coord end T done WHY`)
    | Dropped(why: Text)  /// the work it carried was given up; why says why (`coord end T dropped WHY`)
    | Kept                /// the thread is over; its posts stay as they are
    | Moved(to: Ticket)   /// the owner's words belonged on ticket to and were posted there
    | OneOff              /// old threads only: nothing returns it now
    | Between             /// an agents' thread
  pattern
    match addressed {
      Sent(by) => return Between
      _ =>
        v <- match addressed {
          Named => return Thread
          _ => step watcher intake(text, to)
        };
        match v {
          Place(t) =>
            _ <- post text on t as owner naming typed;
            return Moved(t)
          Thread =>
            _ <- post text as owner naming to, names;
            ...
          Unsure(ts) =>
            _ <- post text as owner naming to, names;
            ...
        }
    }
  when agent_post(p) where p.owner_on do
    q <- step watcher asks(p.text, p.by);
    match q {
      Nothing => return none
      Asks(marks) => mark p marks
    }

program:
r <- match p.all {
  none =>
    match p.answers {
      none =>
        match p.names {
          [] =>
            match (p.naming, p.others) {
              (_, []) =>
                return To(p.naming)
              ([], [a]) =>
                return To([a])
              _ =>
                step watcher route(p.text, p.naming, p.others)
            }
          _ =>
            return To(p.naming)
        }
      _ =>
        return To(p.naming)
    }
  everyone =>
    match everyone {
      [] =>
        return To(p.naming)
      _ =>
        taker <- decide claims(everyone, p.text);
        return To([taker])
    }
};
match r {
  To(as) =>
    tell as p
  Unclear(why) =>
    w <- step owner clarify(p.text, why, p.agents);
    match w {
      Send(as) =>
        tell as p
      Drop =>
        drop p
      Again(t) =>
        tell p.agents p
    }
}

